// Meilisearch write client for the api Worker. The Worker only *indexes* into
// Meilisearch (auto-index on OCR + bulk reindex); clients query Meilisearch
// directly with a read-only key, so there is no search() here. Embeddings are
// generated by Meili itself via the Workers AI REST embedder configured in
// infra/meili/setup-index.mjs.

import { chunkPage } from "./chunk";

const INDEX = "books";

// One indexed document = one *chunk* of a transcribed page. A page is split into
// overlapping chunks (see chunk.ts) so each fits the bge-m3 embedder's ~512-token
// window — long pages no longer lose their tail to truncation. Chunks collapse
// back to one hit per page at query time via distinctAttribute: "file_id".
export interface SearchDoc {
  id: string; // `${file_id}_${chunkIndex}` — Meili primary key (unique per chunk).
  // Separator must be `_`: Meili document ids allow only [A-Za-z0-9_-], so `#`
  // is rejected (the file_id is a hyphenated uuid, already valid).
  file_id: string; // page id: distinct key, reader nav, re-OCR cleanup
  book_id: string;
  book_title: string;
  // Work-level fields, denormalized onto every chunk so the clients can facet by
  // work/author/tags without a join. Null/empty when the copy has no work
  // (work_id NULL). Kept in sync by reindexing a work's books on edit — see
  // lib/reindex.ts.
  work_id: string | null;
  work_name: string | null;
  author: string | null;
  tags: string[];
  page_number: number | null;
  role: string | null;
  text: string; // this chunk's text — searchable + embedded
  page_text: string; // full page markdown — preview display only (not searchable)
}

interface PageInput {
  file_id: string;
  book_id: string;
  book_title: string;
  work_id: string | null;
  work_name: string | null;
  author: string | null;
  tags: string[];
  page_number: number | null;
  role: string | null;
  text: string;
}

// Turn one transcribed page into its chunk documents. Returns [] for empty text.
export function buildPageDocs(page: PageInput): SearchDoc[] {
  return chunkPage(page.text).map((chunk, i) => ({
    id: `${page.file_id}_${i}`,
    file_id: page.file_id,
    book_id: page.book_id,
    book_title: page.book_title,
    work_id: page.work_id,
    work_name: page.work_name,
    author: page.author,
    tags: page.tags,
    page_number: page.page_number,
    role: page.role,
    text: chunk,
    page_text: page.text,
  }));
}

interface MeiliEnv {
  MEILI_URL: string;
  MEILI_KEY: string;
}

async function meili({
  env,
  method,
  path,
  body,
}: {
  env: MeiliEnv;
  method: string;
  path: string;
  body?: unknown;
}): Promise<unknown> {
  const res = await fetch(`${env.MEILI_URL.replace(/\/$/, "")}${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${env.MEILI_KEY}`,
      "Content-Type": "application/json",
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(
      `Meili ${method} ${path} -> ${res.status}: ${JSON.stringify(json)}`,
    );
  }
  return json;
}

// Upsert a batch of chunk documents. Returns Meili's async taskUid. `index`
// defaults to the live index but can target a staging index during a swap build.
export async function upsertDocs({
  env,
  docs,
  index = INDEX,
}: {
  env: MeiliEnv;
  docs: SearchDoc[];
  index?: string;
}): Promise<number> {
  const task = (await meili({
    env,
    method: "POST",
    path: `/indexes/${index}/documents`,
    body: docs,
  })) as { taskUid: number };
  return task.taskUid;
}

// A Meili filter matching one exact value, quoted so ids can't break the syntax.
export const filterEquals = ({
  attribute,
  value,
}: {
  attribute: "book_id" | "work_id";
  value: string;
}): string => `${attribute} = "${value.replace(/["\\]/g, "\\$&")}"`;

// The search fields copied from a book and its work onto every chunk.
export type DenormalizedFields = Partial<
  Pick<SearchDoc, "book_title" | "work_id" | "work_name" | "author" | "tags">
>;

const FETCH_PAGE = 1000;

// Ids of every chunk matching a filter. Fetches only the `id` field.
async function fetchDocIds({
  env,
  filter,
}: {
  env: MeiliEnv;
  filter: string;
}): Promise<string[]> {
  const ids: string[] = [];
  for (let offset = 0; ; offset += FETCH_PAGE) {
    const page = (await meili({
      env,
      method: "POST",
      path: `/indexes/${INDEX}/documents/fetch`,
      body: { filter, fields: ["id"], limit: FETCH_PAGE, offset },
    })) as { results: { id: string }[] };
    ids.push(...page.results.map((r) => r.id));
    if (page.results.length < FETCH_PAGE) return ids;
  }
}

// Set the given fields on every chunk matching `filter`, leaving the text and
// everything else as is. No page is re-read from R2 and nothing is re-embedded
// (the embedder only reads `text`). `skipCreation` (Meili >= 1.31) keeps a chunk
// that a concurrent page reindex just deleted from coming back as a stub.
// Returns Meili's async taskUid, or null when no chunk matched.
export async function patchDocsByFilter({
  env,
  filter,
  fields,
}: {
  env: MeiliEnv;
  filter: string;
  fields: DenormalizedFields;
}): Promise<number | null> {
  const ids = await fetchDocIds({ env, filter });
  if (ids.length === 0) return null;
  const task = (await meili({
    env,
    method: "PUT",
    path: `/indexes/${INDEX}/documents?skipCreation=true`,
    body: ids.map((id) => ({ id, ...fields })),
  })) as { taskUid: number };
  return task.taskUid;
}

// Delete every chunk of one page. Called before re-indexing a page — chunk count
// can change between OCR runs, so stale `file_id#N` docs must be cleared first.
// Tasks are FIFO, so enqueueing this before upsertDocs guarantees ordering.
export async function deleteDocsByFile({
  env,
  fileId,
  index = INDEX,
}: {
  env: MeiliEnv;
  fileId: string;
  index?: string;
}): Promise<number> {
  const task = (await meili({
    env,
    method: "POST",
    path: `/indexes/${index}/documents/delete`,
    body: { filter: `file_id = "${fileId}"` },
  })) as { taskUid: number };
  return task.taskUid;
}

// Delete every chunk document belonging to a book. Uses Meili's delete-by-filter
// (book_id is a filterable attribute); one call regardless of page count.
// Returns Meili's async taskUid.
export async function deleteDocsByBook({
  env,
  bookId,
  index = INDEX,
}: {
  env: MeiliEnv;
  bookId: string;
  index?: string;
}): Promise<number> {
  const task = (await meili({
    env,
    method: "POST",
    path: `/indexes/${index}/documents/delete`,
    body: { filter: `book_id = "${bookId}"` },
  })) as { taskUid: number };
  return task.taskUid;
}

// Drop all documents in the index. Used before a full reindex so the chunk id
// scheme doesn't leave old page-level docs orphaned. Returns Meili's async taskUid.
export async function clearAllDocs({
  env,
}: {
  env: MeiliEnv;
}): Promise<number> {
  const task = (await meili({
    env,
    method: "DELETE",
    path: `/indexes/${INDEX}/documents`,
  })) as { taskUid: number };
  return task.taskUid;
}

// --- Index management (for the zero-downtime swap reindex) ---

// Live search index name. A full rebuild is done into a staging index and then
// atomically swapped in, so the live index is never emptied mid-rebuild.
export const LIVE_INDEX = INDEX;
export const STAGING_INDEX = "books_tmp";

const EMBEDDER = "cfbge";
const EMBED_DIMENSIONS = 1024; // @cf/baai/bge-m3

interface EmbedderEnv {
  CF_ACCOUNT_ID: string;
  CF_AI_TOKEN: string;
}

// The full index settings, kept in lockstep with infra/meili/setup-index.mjs.
// The embedder calls Cloudflare Workers AI at index + query time; its key is the
// CF token now stored as a Worker secret (so a staging index can be built with a
// working embedder without the external bootstrap script).
export function buildIndexSettings(env: EmbedderEnv) {
  return {
    searchableAttributes: ["text", "book_title", "work_name", "author"],
    filterableAttributes: [
      "book_id",
      "book_title",
      "work_id",
      "work_name",
      "author",
      "tags",
      "role",
      "page_number",
      "file_id",
    ],
    sortableAttributes: ["page_number"],
    distinctAttribute: "file_id",
    embedders: {
      [EMBEDDER]: {
        source: "rest",
        url: `https://api.cloudflare.com/client/v4/accounts/${env.CF_ACCOUNT_ID}/ai/run/@cf/baai/bge-m3`,
        apiKey: env.CF_AI_TOKEN,
        dimensions: EMBED_DIMENSIONS,
        request: { text: ["{{text}}", "{{..}}"] },
        response: { result: { data: ["{{embedding}}", "{{..}}"] } },
        documentTemplate: "{{doc.text}}",
      },
    },
  };
}

// Create an index (id primary key). Idempotent: an existing index is fine.
export async function createIndex({
  env,
  index,
}: {
  env: MeiliEnv;
  index: string;
}): Promise<void> {
  try {
    await meili({
      env,
      method: "POST",
      path: "/indexes",
      body: { uid: index, primaryKey: "id" },
    });
  } catch (err) {
    if (!String(err).includes("index_already_exists")) throw err;
  }
}

// Delete an index. Idempotent: a missing index is fine.
export async function deleteIndex({
  env,
  index,
}: {
  env: MeiliEnv;
  index: string;
}): Promise<void> {
  try {
    await meili({ env, method: "DELETE", path: `/indexes/${index}` });
  } catch (err) {
    if (!String(err).includes("index_not_found")) throw err;
  }
}

// Apply index settings (searchable/filterable/embedder/…). Returns the taskUid.
export async function applySettings({
  env,
  index,
  settings,
}: {
  env: MeiliEnv;
  index: string;
  settings: ReturnType<typeof buildIndexSettings>;
}): Promise<number> {
  const task = (await meili({
    env,
    method: "PATCH",
    path: `/indexes/${index}/settings`,
    body: settings,
  })) as { taskUid: number };
  return task.taskUid;
}

// Atomically swap two indexes (their uid→data mapping). One Meili task; queries
// to `a` flip to `b`'s data in a single step, never seeing an empty index.
export async function swapIndexes({
  env,
  a,
  b,
}: {
  env: MeiliEnv;
  a: string;
  b: string;
}): Promise<number> {
  const task = (await meili({
    env,
    method: "POST",
    path: "/swap-indexes",
    body: [{ indexes: [a, b] }],
  })) as { taskUid: number };
  return task.taskUid;
}
